    /// The table the comms image is built against.
    const BOARD_A: &str = "\
otadata, data, ota,     0x9000,   0x2000,
factory, app,  factory, 0x10000,  0x200000,
ota_0,   app,  ota_0,   0x210000, 0x200000,
ota_1,   app,  ota_1,   0x410000, 0x200000,
";

    /// A file of `len` bytes standing in for a built application.
    fn application(scratch: &Scratch, len: usize) -> PathBuf {
        let path = scratch.file("app.bin");
        std::fs::write(&path, vec![0u8; len]).expect("the scratch takes a file");
        path
    }

    fn board_a() -> Table {
        Table::parse(BOARD_A).expect("the table parses")
    }

#[test]
fn f_036_the_slot_route_writes_neither_the_factory_image_nor_the_bootloader() {
    let scratch = Scratch::new().expect("a scratch");
    let table = board_a();
    let plan = plan_slot(&table, &application(&scratch, 176_272), &scratch).expect("a plan");
    keeps_the_recovery_image(&plan, &table).expect("the recovery image is untouched");
    for write in plan.passes.iter().flatten() {
        assert!(
            write.at >= 0x9000,
            "{:#x} is in the bootloader or the partition table",
            write.at
        );
        let end = write.at + write.len;
        assert!(
            write.at >= 0x0021_0000 || end <= 0x0001_0000,
            "{:#x}..{end:#x} overlaps the factory image",
            write.at
        );
    }
}

pub fn plan_slot(table: &Table, app: &Path, scratch: &Scratch) -> Result<Plan> {
    let otadata = table.find(Role::OTA_DATA)?;
    if otadata.size != OTADATA_LEN {
        bail!("{otadata} is not the {OTADATA_LEN:#x} bytes the bootloader reads");
    }
    let role = Role::ota(BENCH_SLOT);
    let slot = table.find(role)?;
    let app_len = u32::try_from(
        std::fs::metadata(app)
            .with_context(|| format!("measuring {}", app.display()))?
            .len(),
    )
    .context("an application that fits a u32")?;
    if app_len > slot.size {
        bail!("the application is {app_len} bytes and {slot} holds it not");
    }
    let blank = scratch.file("otadata-blank.bin");
    std::fs::write(&blank, otadata_no_slot())
        .with_context(|| format!("writing {}", blank.display()))?;
    let selecting = scratch.file("otadata-slot.bin");
    std::fs::write(
        &selecting,
        otadata_selecting(u32::from(BENCH_SLOT), OTA_SLOTS, ImageState::New)?,
    )
    .with_context(|| format!("writing {}", selecting.display()))?;
    let plan = Plan {
        says: format!(
            "writing the application into {} ({role}) at {:#x}; the bootloader, the partition table and the factory image stay",
            slot.name, slot.offset
        ),
        passes: vec![
            vec![
                Write {
                    at: otadata.offset,
                    len: OTADATA_LEN,
                    file: blank,
                },
                Write {
                    at: slot.offset,
                    len: app_len,
                    file: app.to_path_buf(),
                },
            ],
            vec![Write {
                at: otadata.offset,
                len: OTADATA_LEN,
                file: selecting,
            }],
        ],
    };
    // Each write inside the partition it is for, by the sectors it
    // erases: the plan's promise is the two partitions and nothing else.
    for pass in &plan.passes {
        for write in pass {
            let partition = if write.at == otadata.offset {
                otadata
            } else {
                slot
            };
            within(write, partition)?;
        }
    }
    keeps_the_recovery_image(&plan, table)?;
    Ok(plan)
}

pub fn keeps_the_recovery_image(plan: &Plan, table: &Table) -> Result<()> {
    let factory = table.find(Role::FACTORY)?;
    let factory_end = factory.end()?;
    for write in plan.passes.iter().flatten() {
        // The sectors the write erases, not the bytes it means to change.
        let (first, end) = erased(write)?;
        if first < PARTITION_TABLE_END {
            bail!(
                "a write of {} bytes at {:#x} erases into the bootloader or the partition table",
                write.len,
                write.at
            );
        }
        if first < factory_end && end > factory.offset {
            bail!(
                "a write of {} bytes at {:#x} erases into {factory}, which carries the \
                 download window",
                write.len,
                write.at
            );
        }
    }
    Ok(())
}

#[test]
fn production_table_reserves_recovery_ota_credentials_and_assets() {
    // This checks the shipped layout, not the factory image's contents or
    // the download window's lifetime. F-036 remains uncovered.
    let table = Table::parse(include_str!("../../../firmwares/o89-comms/partitions.csv"))
        .expect("the production table parses");
    let expected = [
        ("otadata", Role::OTA_DATA, 0x9000, 0x2000),
        ("factory", Role::FACTORY, 0x0001_0000, 0x0020_0000),
        ("ota_0", Role::ota(0), 0x0021_0000, 0x0020_0000),
        ("ota_1", Role::ota(1), 0x0041_0000, 0x0020_0000),
        (
            "creds",
            Role {
                kind: 1,
                subtype: 0x02,
            },
            0x0061_0000,
            0x6000,
        ),
        (
            "assets",
            Role {
                kind: 1,
                subtype: 0x82,
            },
            0x0061_6000,
            0x001e_a000,
        ),
    ];
    assert_eq!(table.partitions.len(), expected.len());
    for (name, role, offset, size) in expected {
        let partition = table.find(role).expect("the required partition exists");
        assert_eq!(partition.name, name);
        assert_eq!((partition.offset, partition.size), (offset, size), "{name}");
    }
}

pub fn find(&self, role: Role) -> Result<&Partition> {
    let mut matching = self
        .partitions
        .iter()
        .filter(|partition| partition.role == Some(role));
    let found = matching.next().with_context(|| {
        let rows: Vec<String> = self
            .partitions
            .iter()
            .map(|p| match p.role {
                Some(role) => format!("{} ({role})", p.name),
                None => format!("{} (a type this tool does not know)", p.name),
            })
            .collect();
        format!("no {role} partition; the table has {}", rows.join(", "))
    })?;
    if let Some(again) = matching.next() {
        bail!(
            "the table declares {role} twice, as {} and as {}",
            found.name,
            again.name
        );
    }
    Ok(found)
}

pub fn parse(text: &str) -> Result<Self> {
    let mut partitions = Vec::new();
    for (number, line) in text.lines().enumerate() {
        let line = line.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        let line_number = number.saturating_add(1);
        partitions.push(
            Partition::parse(line)
                .with_context(|| format!("on line {line_number}: {line:?}"))?,
        );
    }
    if partitions.is_empty() {
        bail!("no partitions in the table");
    }
    Ok(Self { partitions })
}

